"""
Tests for nv_optimizer.core.experts

Written from interface contracts in .team/specs/interfaces.py.
"""
import pytest

from nv_optimizer.core.experts import (
    ALL_EXPERTS,
    ARCHITECT,
    BACKEND,
    DEVOPS,
    FRONTEND,
    RESEARCHER,
    REVIEWER,
    TESTER,
    ExpertDefinition,
    get_expert,
    list_experts,
    render_spawn_prompt,
)


EXPECTED_EXPERT_KEYS = {
    "architect", "frontend", "backend", "tester", "reviewer", "devops", "researcher"
}


# ── ExpertDefinition structure ────────────────────────────────────

class TestExpertDefinitionStructure:
    def test_expert_definition_is_dataclass(self):
        assert hasattr(ExpertDefinition, "__dataclass_fields__")

    def test_expert_definition_is_frozen(self):
        expert = get_expert("architect")
        with pytest.raises((AttributeError, TypeError)):
            expert.key = "modified"  # type: ignore[misc]

    def test_all_required_fields_present(self):
        fields = {"key", "label", "icon", "color", "keywords", "tools", "file_scope",
                  "default_model", "spawn_template"}
        for expert in ALL_EXPERTS.values():
            for field in fields:
                assert hasattr(expert, field), f"Expert {expert.key!r} missing field {field!r}"


# ── All 7 experts defined ─────────────────────────────────────────

class TestAllExpertsDefined:
    def test_all_seven_experts_in_all_experts(self):
        assert set(ALL_EXPERTS.keys()) == EXPECTED_EXPERT_KEYS

    def test_module_level_constants_match_all_experts(self):
        assert ALL_EXPERTS["architect"] is ARCHITECT
        assert ALL_EXPERTS["frontend"] is FRONTEND
        assert ALL_EXPERTS["backend"] is BACKEND
        assert ALL_EXPERTS["tester"] is TESTER
        assert ALL_EXPERTS["reviewer"] is REVIEWER
        assert ALL_EXPERTS["devops"] is DEVOPS
        assert ALL_EXPERTS["researcher"] is RESEARCHER

    def test_architect_expert_defined(self):
        assert ARCHITECT.key == "architect"

    def test_frontend_expert_defined(self):
        assert FRONTEND.key == "frontend"

    def test_backend_expert_defined(self):
        assert BACKEND.key == "backend"

    def test_tester_expert_defined(self):
        assert TESTER.key == "tester"

    def test_reviewer_expert_defined(self):
        assert REVIEWER.key == "reviewer"

    def test_devops_expert_defined(self):
        assert DEVOPS.key == "devops"

    def test_researcher_expert_defined(self):
        assert RESEARCHER.key == "researcher"


# ── Keyword sets non-empty ────────────────────────────────────────

class TestKeywordSets:
    def test_all_experts_have_non_empty_keywords(self):
        for key, expert in ALL_EXPERTS.items():
            assert len(expert.keywords) > 0, f"Expert {key!r} has empty keywords"

    def test_keywords_are_lowercase(self):
        for key, expert in ALL_EXPERTS.items():
            for kw in expert.keywords:
                assert kw == kw.lower(), (
                    f"Expert {key!r} keyword {kw!r} is not lowercase"
                )

    def test_architect_has_architecture_keywords(self):
        kws = set(ARCHITECT.keywords)
        # Must have at least one architecture-related keyword
        architecture_related = {"architect", "architecture", "interface", "design",
                                 "schema", "contract", "system-design", "system"}
        assert kws & architecture_related, (
            f"Architect keywords {kws!r} lack architecture terms"
        )

    def test_frontend_has_ui_keywords(self):
        kws = set(FRONTEND.keywords)
        ui_related = {"ui", "component", "react", "css", "form", "page", "layout", "view"}
        assert kws & ui_related, f"Frontend keywords {kws!r} lack UI terms"

    def test_backend_has_api_keywords(self):
        kws = set(BACKEND.keywords)
        api_related = {"api", "endpoint", "server", "database", "auth", "route",
                       "middleware", "migration"}
        assert kws & api_related, f"Backend keywords {kws!r} lack API terms"

    def test_tester_has_test_keywords(self):
        kws = set(TESTER.keywords)
        test_related = {"test", "spec", "coverage", "e2e", "qa", "validate", "unit-test"}
        assert kws & test_related, f"Tester keywords {kws!r} lack test terms"

    def test_reviewer_has_review_keywords(self):
        kws = set(REVIEWER.keywords)
        review_related = {"review", "audit", "security", "performance", "refactor", "lint"}
        assert kws & review_related, f"Reviewer keywords {kws!r} lack review terms"

    def test_devops_has_deploy_keywords(self):
        kws = set(DEVOPS.keywords)
        devops_related = {"deploy", "docker", "ci", "cd", "infra", "config",
                          "pipeline", "build", "env"}
        assert kws & devops_related, f"DevOps keywords {kws!r} lack devops terms"

    def test_researcher_has_research_keywords(self):
        kws = set(RESEARCHER.keywords)
        research_related = {"research", "investigate", "compare", "analyze",
                            "hypothesis", "benchmark"}
        assert kws & research_related, f"Researcher keywords {kws!r} lack research terms"


# ── Default models ────────────────────────────────────────────────

class TestDefaultModels:
    def test_all_default_models_valid(self):
        valid_models = {"opus", "sonnet", "haiku"}
        for key, expert in ALL_EXPERTS.items():
            assert expert.default_model in valid_models, (
                f"Expert {key!r} has invalid default_model {expert.default_model!r}"
            )

    def test_architect_uses_opus(self):
        # Architect is the most complex role — should use opus
        assert ARCHITECT.default_model == "opus"


# ── Spawn templates ───────────────────────────────────────────────

class TestSpawnTemplates:
    def test_all_experts_have_spawn_template(self):
        for key, expert in ALL_EXPERTS.items():
            assert isinstance(expert.spawn_template, str)
            assert len(expert.spawn_template.strip()) > 0, (
                f"Expert {key!r} has empty spawn_template"
            )

    def test_spawn_templates_contain_tasks_placeholder(self):
        for key, expert in ALL_EXPERTS.items():
            assert "{tasks}" in expert.spawn_template, (
                f"Expert {key!r} spawn_template missing {{tasks}} placeholder"
            )


# ── get_expert ────────────────────────────────────────────────────

class TestGetExpert:
    def test_returns_correct_expert(self):
        for key in EXPECTED_EXPERT_KEYS:
            expert = get_expert(key)
            assert expert.key == key

    def test_raises_key_error_for_unknown_key(self):
        with pytest.raises(KeyError):
            get_expert("nonexistent_expert")

    def test_returns_expert_definition_instance(self):
        result = get_expert("backend")
        assert isinstance(result, ExpertDefinition)


# ── list_experts ──────────────────────────────────────────────────

class TestListExperts:
    def test_returns_all_7_experts(self):
        experts = list_experts()
        assert len(experts) == 7

    def test_all_expert_keys_present(self):
        experts = list_experts()
        keys = {e.key for e in experts}
        assert keys == EXPECTED_EXPERT_KEYS

    def test_sorted_by_key(self):
        experts = list_experts()
        keys = [e.key for e in experts]
        assert keys == sorted(keys)

    def test_returns_list_of_expert_definitions(self):
        experts = list_experts()
        assert isinstance(experts, list)
        for e in experts:
            assert isinstance(e, ExpertDefinition)


# ── render_spawn_prompt ───────────────────────────────────────────

class TestRenderSpawnPrompt:
    def test_renders_without_error(self):
        expert = get_expert("backend")
        result = render_spawn_prompt(expert, ["Build login API", "Add JWT auth"])
        assert isinstance(result, str)

    def test_includes_all_task_descriptions(self):
        tasks = ["Build login form", "Add password reset", "Write unit tests"]
        expert = get_expert("frontend")
        result = render_spawn_prompt(expert, tasks)
        for task in tasks:
            assert task in result, f"Task {task!r} not found in rendered prompt"

    def test_single_task_renders(self):
        expert = get_expert("tester")
        result = render_spawn_prompt(expert, ["Write integration tests"])
        assert "Write integration tests" in result

    def test_empty_task_list_renders_without_error(self):
        expert = get_expert("devops")
        result = render_spawn_prompt(expert, [])
        assert isinstance(result, str)

    def test_tasks_appear_as_numbered_list(self):
        tasks = ["Task Alpha", "Task Beta", "Task Gamma"]
        expert = get_expert("researcher")
        result = render_spawn_prompt(expert, tasks)
        # Should contain numbering (1. or 1:)
        assert "1" in result

    def test_all_experts_render_spawn_prompts(self):
        tasks = ["Sample task one", "Sample task two"]
        for key in EXPECTED_EXPERT_KEYS:
            expert = get_expert(key)
            result = render_spawn_prompt(expert, tasks)
            assert isinstance(result, str)
            assert len(result) > 0

"""
Tests for nv_optimizer.output.prompt_gen

Written from interface contracts in .team/specs/interfaces.py.
"""
import pytest

from nv_optimizer.core.budget import (
    CheckpointPlan,
    CostEstimate,
    ModelTierPlan,
)
from nv_optimizer.core.resource_model import ResourceProfile
from nv_optimizer.output.prompt_gen import ExecutionPlan, generate_execution_plan


# ── Fixtures ──────────────────────────────────────────────────────

def _make_resource_profile(**kwargs):
    defaults = dict(
        base_context_tokens=13_000,
        per_task_tokens=14_000,
        usable_context=170_000,
        max_tasks_per_agent=10,
        effective_capacity=165_000,
        context_pressure=0.16,
    )
    defaults.update(kwargs)
    return ResourceProfile(**defaults)


def _make_model_tiers(**kwargs):
    defaults = dict(lead="opus", workers="sonnet", reviewers="haiku", rationale="test plan")
    defaults.update(kwargs)
    return ModelTierPlan(**defaults)


def _make_checkpoint_plan(**kwargs):
    defaults = dict(enabled=False, strategy="none", checkpoint_every=None, rationale="low pressure")
    defaults.update(kwargs)
    return CheckpointPlan(**defaults)


def _make_cost_estimate(**kwargs):
    defaults = dict(
        total_tokens=100_000,
        total_cost_usd=1.50,
        lead_cost_usd=0.50,
        worker_cost_usd=1.00,
        cost_per_task_usd=0.30,
    )
    defaults.update(kwargs)
    return CostEstimate(**defaults)


def _make_routing(tasks=None):
    if tasks is None:
        tasks = ["Build login form", "Add auth API", "Write tests"]
    return {
        "frontend": ["Build login form"],
        "backend": ["Add auth API"],
        "tester": ["Write tests"],
    }


def _call_generate(
    project_name="MyProject",
    routing=None,
    strategy="teams",
    num_agents=4,
    waves=2,
    **kwargs,
):
    if routing is None:
        routing = _make_routing()
    return generate_execution_plan(
        project_name=project_name,
        routing=routing,
        resource_profile=_make_resource_profile(),
        model_tiers=_make_model_tiers(),
        checkpoint_plan=_make_checkpoint_plan(),
        cost_estimate=_make_cost_estimate(),
        orchestration_strategy=strategy,
        num_agents=num_agents,
        waves=waves,
        **kwargs,
    )


# ── ExecutionPlan structure ───────────────────────────────────────

class TestExecutionPlanStructure:
    def test_is_frozen_dataclass(self):
        plan = _call_generate()
        with pytest.raises((AttributeError, TypeError)):
            plan.kickoff_prompt = "modified"  # type: ignore[misc]

    def test_all_fields_present(self):
        plan = _call_generate()
        assert hasattr(plan, "env_setup")
        assert hasattr(plan, "kickoff_prompt")
        assert hasattr(plan, "spawn_prompts")
        assert hasattr(plan, "claude_md_snippet")
        assert hasattr(plan, "summary")

    def test_returns_execution_plan_instance(self):
        result = _call_generate()
        assert isinstance(result, ExecutionPlan)


# ── Kickoff prompt ────────────────────────────────────────────────

class TestKickoffPrompt:
    def test_kickoff_prompt_includes_project_name(self):
        plan = _call_generate(project_name="AwesomeApp")
        assert "AwesomeApp" in plan.kickoff_prompt

    def test_kickoff_prompt_is_non_empty(self):
        plan = _call_generate()
        assert len(plan.kickoff_prompt.strip()) > 0

    def test_kickoff_prompt_is_string(self):
        plan = _call_generate()
        assert isinstance(plan.kickoff_prompt, str)

    def test_kickoff_prompt_different_projects(self):
        plan_a = _call_generate(project_name="ProjectAlpha")
        plan_b = _call_generate(project_name="ProjectBeta")
        assert plan_a.kickoff_prompt != plan_b.kickoff_prompt


# ── Spawn prompts ─────────────────────────────────────────────────

class TestSpawnPrompts:
    def test_spawn_prompts_generated_for_each_active_expert(self):
        routing = {
            "frontend": ["Build React form"],
            "backend": ["Add JWT auth"],
            "tester": ["Write e2e tests"],
        }
        plan = _call_generate(routing=routing)
        assert isinstance(plan.spawn_prompts, dict)
        for expert_key in routing:
            assert expert_key in plan.spawn_prompts, (
                f"Expected spawn prompt for expert {expert_key!r}"
            )

    def test_spawn_prompts_is_dict(self):
        plan = _call_generate()
        assert isinstance(plan.spawn_prompts, dict)

    def test_spawn_prompts_all_strings(self):
        plan = _call_generate()
        for key, prompt in plan.spawn_prompts.items():
            assert isinstance(prompt, str), f"Spawn prompt for {key!r} is not a string"
            assert len(prompt.strip()) > 0, f"Spawn prompt for {key!r} is empty"

    def test_spawn_prompts_contain_tasks(self):
        routing = {
            "backend": ["Add JWT auth middleware", "Create user registration endpoint"],
        }
        plan = _call_generate(routing=routing)
        backend_prompt = plan.spawn_prompts.get("backend", "")
        assert "JWT auth middleware" in backend_prompt or "Add JWT" in backend_prompt

    def test_empty_routing_yields_no_spawn_prompts(self):
        plan = _call_generate(routing={})
        assert plan.spawn_prompts == {} or len(plan.spawn_prompts) == 0


# ── CLAUDE.md snippet ─────────────────────────────────────────────

class TestClaudeMdSnippet:
    def test_claude_md_snippet_is_string(self):
        plan = _call_generate()
        assert isinstance(plan.claude_md_snippet, str)

    def test_claude_md_snippet_non_empty(self):
        plan = _call_generate()
        assert len(plan.claude_md_snippet.strip()) > 0

    def test_claude_md_snippet_includes_coordination_rules(self):
        plan = _call_generate()
        snippet = plan.claude_md_snippet.lower()
        # Should contain some coordination/team-related content
        coordination_terms = {"team", "agent", "expert", "coordinate", "role", "coordination"}
        assert any(term in snippet for term in coordination_terms), (
            f"CLAUDE.md snippet lacks coordination terms: {plan.claude_md_snippet[:200]!r}"
        )

    def test_claude_md_snippet_includes_project_name(self):
        plan = _call_generate(project_name="SuperProject")
        assert "SuperProject" in plan.claude_md_snippet


# ── env_setup ─────────────────────────────────────────────────────

class TestEnvSetup:
    def test_env_setup_is_string(self):
        plan = _call_generate()
        assert isinstance(plan.env_setup, str)

    def test_teams_strategy_includes_env_setup(self):
        plan = _call_generate(strategy="teams")
        # Teams strategy should have env setup commands (export or set)
        assert len(plan.env_setup.strip()) > 0

    def test_env_setup_contains_export_or_set(self):
        plan = _call_generate(strategy="teams")
        # Should contain some env var setup
        env_lower = plan.env_setup.lower()
        assert "export" in env_lower or "set" in env_lower or "=" in plan.env_setup


# ── Summary ───────────────────────────────────────────────────────

class TestSummary:
    def test_summary_is_string(self):
        plan = _call_generate()
        assert isinstance(plan.summary, str)

    def test_summary_non_empty(self):
        plan = _call_generate()
        assert len(plan.summary.strip()) > 0

    def test_summary_mentions_agent_count(self):
        plan = _call_generate(num_agents=5)
        assert "5" in plan.summary or "five" in plan.summary.lower()

    def test_summary_different_for_different_strategies(self):
        solo_plan = _call_generate(strategy="solo", num_agents=1, waves=1)
        teams_plan = _call_generate(strategy="teams", num_agents=5, waves=2)
        # At minimum they should not be identical
        assert solo_plan.summary != teams_plan.summary or True  # soft check, no crash


# ── Overall generation ────────────────────────────────────────────

class TestGenerateExecutionPlan:
    def test_no_exception_for_all_strategies(self):
        for strategy in ("solo", "subagents", "teams"):
            plan = _call_generate(strategy=strategy)
            assert isinstance(plan, ExecutionPlan)

    def test_different_projects_produce_different_plans(self):
        plan_a = _call_generate(project_name="AlphaProject")
        plan_b = _call_generate(project_name="BetaProject")
        # At least the kickoff_prompt should differ
        assert plan_a.kickoff_prompt != plan_b.kickoff_prompt or \
               plan_a.claude_md_snippet != plan_b.claude_md_snippet

    def test_checkpointing_reflected_in_output(self):
        # When checkpointing is enabled, it should appear somewhere in the plan
        ckpt = CheckpointPlan(
            enabled=True,
            strategy="aggressive",
            checkpoint_every=2,
            rationale="high pressure",
        )
        plan = generate_execution_plan(
            project_name="TestProject",
            routing=_make_routing(),
            resource_profile=_make_resource_profile(),
            model_tiers=_make_model_tiers(),
            checkpoint_plan=ckpt,
            cost_estimate=_make_cost_estimate(),
            orchestration_strategy="teams",
            num_agents=4,
            waves=2,
        )
        full_output = (
            plan.kickoff_prompt + plan.claude_md_snippet + plan.summary + plan.env_setup
        ).lower()
        checkpoint_terms = {"checkpoint", "summarize", "summarization", "aggressive"}
        assert any(term in full_output for term in checkpoint_terms)

"""
Tests for nv_optimizer.presets

Written from interface contracts in .team/specs/interfaces.py.
"""
import pytest

from nv_optimizer.presets import (
    ALL_PRESETS,
    BUG_TRIAGE,
    DOCS,
    FEATURE_BUILD,
    QA_SWARM,
    REFACTOR,
    RESEARCH,
    Preset,
    apply_preset,
    get_preset,
    list_presets,
)

EXPECTED_PRESET_NAMES = {
    "refactor", "feature_build", "bug_triage", "qa_swarm", "research", "docs"
}

VALID_COMPLEXITIES = ("trivial", "low", "medium", "high", "extreme")
VALID_CODEBASE_SIZES = ("small", "medium", "large", "massive")
VALID_BUDGETS = ("tight", "normal", "unlimited")


# ── Preset structure ──────────────────────────────────────────────

class TestPresetStructure:
    def test_preset_is_frozen_dataclass(self):
        with pytest.raises((AttributeError, TypeError)):
            REFACTOR.complexity = "low"  # type: ignore[misc]

    def test_all_required_fields_present(self):
        fields = {"name", "description", "complexity", "codebase_size",
                  "budget", "needs_comms", "model_override"}
        for name, preset in ALL_PRESETS.items():
            for field in fields:
                assert hasattr(preset, field), (
                    f"Preset {name!r} missing field {field!r}"
                )

    def test_all_complexity_values_valid(self):
        for name, preset in ALL_PRESETS.items():
            assert preset.complexity in VALID_COMPLEXITIES, (
                f"Preset {name!r} has invalid complexity {preset.complexity!r}"
            )

    def test_all_codebase_size_values_valid(self):
        for name, preset in ALL_PRESETS.items():
            assert preset.codebase_size in VALID_CODEBASE_SIZES, (
                f"Preset {name!r} has invalid codebase_size {preset.codebase_size!r}"
            )

    def test_all_budget_values_valid(self):
        for name, preset in ALL_PRESETS.items():
            assert preset.budget in VALID_BUDGETS, (
                f"Preset {name!r} has invalid budget {preset.budget!r}"
            )

    def test_needs_comms_is_bool(self):
        for name, preset in ALL_PRESETS.items():
            assert isinstance(preset.needs_comms, bool), (
                f"Preset {name!r} needs_comms is not bool"
            )

    def test_model_override_is_none_or_valid(self):
        valid_models = {"opus", "sonnet", "haiku", None}
        for name, preset in ALL_PRESETS.items():
            assert preset.model_override in valid_models, (
                f"Preset {name!r} has invalid model_override {preset.model_override!r}"
            )

    def test_description_non_empty(self):
        for name, preset in ALL_PRESETS.items():
            assert isinstance(preset.description, str)
            assert len(preset.description.strip()) > 0, (
                f"Preset {name!r} has empty description"
            )


# ── All 6 presets defined ─────────────────────────────────────────

class TestAllPresetsDefined:
    def test_all_preset_names_in_all_presets(self):
        assert set(ALL_PRESETS.keys()) == EXPECTED_PRESET_NAMES

    def test_module_constants_match_all_presets(self):
        assert ALL_PRESETS["refactor"] is REFACTOR
        assert ALL_PRESETS["feature_build"] is FEATURE_BUILD
        assert ALL_PRESETS["bug_triage"] is BUG_TRIAGE
        assert ALL_PRESETS["qa_swarm"] is QA_SWARM
        assert ALL_PRESETS["research"] is RESEARCH
        assert ALL_PRESETS["docs"] is DOCS

    def test_refactor_preset_values(self):
        assert REFACTOR.complexity == "medium"
        assert REFACTOR.codebase_size == "large"
        assert REFACTOR.needs_comms is True

    def test_feature_build_preset_values(self):
        assert FEATURE_BUILD.complexity == "high"
        assert FEATURE_BUILD.codebase_size == "medium"
        assert FEATURE_BUILD.needs_comms is True

    def test_bug_triage_preset_values(self):
        assert BUG_TRIAGE.complexity == "medium"
        assert BUG_TRIAGE.codebase_size == "medium"
        assert BUG_TRIAGE.needs_comms is False

    def test_qa_swarm_preset_values(self):
        assert QA_SWARM.complexity == "low"
        assert QA_SWARM.codebase_size == "medium"
        assert QA_SWARM.needs_comms is True

    def test_research_preset_values(self):
        assert RESEARCH.complexity == "high"
        assert RESEARCH.codebase_size == "medium"
        assert RESEARCH.needs_comms is True

    def test_docs_preset_values(self):
        assert DOCS.complexity == "low"
        assert DOCS.codebase_size == "large"
        assert DOCS.needs_comms is False
        assert DOCS.budget == "tight"


# ── get_preset ────────────────────────────────────────────────────

class TestGetPreset:
    def test_returns_correct_preset(self):
        for name in EXPECTED_PRESET_NAMES:
            preset = get_preset(name)
            assert preset.name == name

    def test_returns_preset_instance(self):
        result = get_preset("refactor")
        assert isinstance(result, Preset)

    def test_raises_key_error_for_unknown_name(self):
        with pytest.raises(KeyError):
            get_preset("nonexistent_preset")

    def test_raises_key_error_for_empty_string(self):
        with pytest.raises(KeyError):
            get_preset("")


# ── list_presets ──────────────────────────────────────────────────

class TestListPresets:
    def test_returns_all_6_presets(self):
        presets = list_presets()
        assert len(presets) == 6

    def test_all_preset_names_present(self):
        presets = list_presets()
        names = {p.name for p in presets}
        assert names == EXPECTED_PRESET_NAMES

    def test_sorted_by_name(self):
        presets = list_presets()
        names = [p.name for p in presets]
        assert names == sorted(names)

    def test_returns_list_of_preset_instances(self):
        presets = list_presets()
        assert isinstance(presets, list)
        for p in presets:
            assert isinstance(p, Preset)


# ── apply_preset ──────────────────────────────────────────────────

class TestApplyPreset:
    def test_preset_fills_unspecified_values(self):
        result = apply_preset(REFACTOR, explicit_overrides={})
        assert "complexity" in result
        assert result["complexity"] == REFACTOR.complexity

    def test_explicit_overrides_win_over_preset(self):
